import React, { useState, useEffect } from 'react';
import { Box, TextField, Button, Typography, IconButton, LinearProgress } from '@mui/material';
import { styled, keyframes } from '@mui/material/styles';
import { useNavigate } from 'react-router-dom';
import MicIcon from '@mui/icons-material/Mic';
import FingerprintIcon from '@mui/icons-material/Fingerprint';
import QrCode2Icon from '@mui/icons-material/QrCode2';

// Keyframe animations
const glitch = keyframes`
  0% { 
    text-shadow: 0.05em 0 0 #00ff9d,
                -0.05em -0.025em 0 #ff00e6,
                -0.025em 0.05em 0 #0011ff;
  }
  14% {
    text-shadow: 0.05em 0 0 #00ff9d,
                -0.05em -0.025em 0 #ff00e6,
                -0.025em 0.05em 0 #0011ff;
  }
  15% {
    text-shadow: -0.05em -0.025em 0 #00ff9d,
                0.025em 0.025em 0 #ff00e6,
                -0.05em -0.05em 0 #0011ff;
  }
  49% {
    text-shadow: -0.05em -0.025em 0 #00ff9d,
                0.025em 0.025em 0 #ff00e6,
                -0.05em -0.05em 0 #0011ff;
  }
  50% {
    text-shadow: 0.025em 0.05em 0 #00ff9d,
                0.05em 0 0 #ff00e6,
                0 -0.05em 0 #0011ff;
  }
  99% {
    text-shadow: 0.025em 0.05em 0 #00ff9d,
                0.05em 0 0 #ff00e6,
                0 -0.05em 0 #0011ff;
  }
  100% {
    text-shadow: -0.025em 0 0 #00ff9d,
                -0.025em -0.025em 0 #ff00e6,
                -0.025em -0.05em 0 #0011ff;
  }
`;

const scan = keyframes`
  from {
    transform: translateY(-100%) rotate(15deg);
  }
  to {
    transform: translateY(100%) rotate(15deg);
  }
`;

const binaryRain = keyframes`
  0% {
    transform: translateY(-100%);
    opacity: 1;
  }
  85% {
    opacity: 1;
  }
  100% {
    transform: translateY(1000%);
    opacity: 0;
  }
`;

const pulse = keyframes`
  0% {
    box-shadow: 0 0 15px #00f7ff80;
  }
  50% {
    box-shadow: 0 0 30px #00f7ff;
  }
  100% {
    box-shadow: 0 0 15px #00f7ff80;
  }
`;

const gradientShift = keyframes`
  0% {
    background-position: 0% 50%;
  }
  50% {
    background-position: 100% 50%;
  }
  100% {
    background-position: 0% 50%;
  }
`;

// Styled components
const LoginContainer = styled(Box)(({ theme }) => ({
  background: 'linear-gradient(135deg, #1a1f35 0%, #242b4a 50%, #1a1f35 100%)',
  backgroundSize: '200% 200%',
  animation: `${gradientShift} 15s ease infinite`,
  minHeight: '100vh',
  minWidth: '100vw',
  display: 'flex',
  flexDirection: 'column',
  alignItems: 'center',
  justifyContent: 'center',
  position: 'relative',
  overflow: 'hidden',
  padding: theme.spacing(2),
  [theme.breakpoints.up('sm')]: {
    padding: theme.spacing(3),
  },
  '&::before': {
    content: '""',
    position: 'absolute',
    top: 0,
    left: 0,
    right: 0,
    bottom: 0,
    background: 'radial-gradient(circle at 50% 50%, rgba(13, 19, 45, 0.7) 0%, rgba(13, 19, 45, 0.95) 100%)',
    zIndex: 1,
  },
  '&::after': {
    content: '"01010101"',
    position: 'absolute',
    color: '#00ffaa20',
    fontSize: '16px',
    [theme.breakpoints.up('sm')]: {
      fontSize: '20px',
    },
    width: '100%',
    textAlign: 'center',
    animation: `${binaryRain} 10s linear infinite`,
    top: 0,
    zIndex: 2,
  },
}));

const GlassPanel = styled(Box)(({ theme }) => ({
  background: 'rgba(13, 19, 45, 0.65)',
  backdropFilter: 'blur(10px)',
  borderRadius: '16px',
  padding: theme.spacing(3),
  width: '100%',
  maxWidth: '90%',
  [theme.breakpoints.up('sm')]: {
    padding: theme.spacing(4),
    maxWidth: '400px',
  },
  position: 'relative',
  zIndex: 3,
  border: '1px solid rgba(255, 255, 255, 0.05)',
  boxShadow: '0 4px 20px rgba(0, 0, 0, 0.15)',
}));

const GlitchTitle = styled(Typography)(({ theme }) => ({
  color: '#fff',
  marginBottom: theme.spacing(3),
  textAlign: 'center',
  animation: `${glitch} 2s infinite alternate`,
  fontSize: '2rem',
  [theme.breakpoints.up('sm')]: {
    fontSize: '2.5rem',
    marginBottom: theme.spacing(4),
  },
  fontWeight: 'bold',
  letterSpacing: '2px',
  userSelect: 'none',
}));

const CyberInput = styled(TextField)(({ theme }) => ({
  marginBottom: theme.spacing(2),
  '& .MuiOutlinedInput-root': {
    color: '#fff',
    background: 'rgba(15, 15, 30, 0.7)',
    border: '1px solid #00f7ff',
    boxShadow: '0 0 15px #00f7ff80',
    height: '48px',
    [theme.breakpoints.up('sm')]: {
      height: '56px',
    },
    '&:hover': {
      borderColor: '#00f7ff',
      boxShadow: '0 0 20px #00f7ff',
    },
    '&.Mui-focused': {
      borderColor: '#00f7ff',
      boxShadow: '0 0 25px #00f7ff',
    },
    '& input': {
      padding: '12px 14px',
      [theme.breakpoints.up('sm')]: {
        padding: '16px',
      },
      '&::placeholder': {
        color: '#00f7ff',
        opacity: 0.7,
        fontSize: '0.85rem',
        [theme.breakpoints.up('sm')]: {
          fontSize: '0.9rem',
        },
        letterSpacing: '1px',
      },
    },
  },
  '& .MuiOutlinedInput-notchedOutline': {
    borderColor: '#00f7ff',
    border: 'none',
  },
}));

const CyberButton = styled(Button)(({ theme }) => ({
  background: 'linear-gradient(45deg, #00f7ff, #7b2dff)',
  color: '#fff',
  padding: '10px',
  [theme.breakpoints.up('sm')]: {
    padding: theme.spacing(1.5),
  },
  marginTop: theme.spacing(2),
  position: 'relative',
  overflow: 'hidden',
  animation: `${pulse} 2s infinite`,
  fontSize: '0.9rem',
  [theme.breakpoints.up('sm')]: {
    fontSize: '1rem',
  },
  height: '48px',
  [theme.breakpoints.up('sm')]: {
    height: '56px',
  },
  '&:hover': {
    background: 'linear-gradient(45deg, #00f7ff, #7b2dff)',
    '&::after': {
      content: '""',
      position: 'absolute',
      top: '-50%',
      left: '-50%',
      width: '200%',
      height: '200%',
      background: 'linear-gradient(to bottom right, transparent 45%, #ffffff80 50%, transparent 55%)',
      animation: `${scan} 2s linear infinite`,
    },
  },
}));

const AlternativeLogin = styled(Box)(({ theme }) => ({
  display: 'flex',
  justifyContent: 'center',
  gap: theme.spacing(2),
  marginTop: theme.spacing(2),
  [theme.breakpoints.up('sm')]: {
    marginTop: theme.spacing(3),
    gap: theme.spacing(3),
  },
}));

const IconWrapper = styled(IconButton)(({ theme }) => ({
  color: '#00f7ff',
  border: '1px solid #00f7ff',
  padding: theme.spacing(1),
  width: '40px',
  height: '40px',
  [theme.breakpoints.up('sm')]: {
    width: '48px',
    height: '48px',
  },
  '&:hover': {
    background: 'rgba(0, 247, 255, 0.1)',
    boxShadow: '0 0 15px #00f7ff80',
  },
  '& .MuiSvgIcon-root': {
    fontSize: '1.2rem',
    [theme.breakpoints.up('sm')]: {
      fontSize: '1.5rem',
    },
  },
}));

function Login() {
  const [username, setUsername] = useState('');
  const [password, setPassword] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [loadingProgress, setLoadingProgress] = useState(0);
  const navigate = useNavigate();

  useEffect(() => {
    if (isLoading) {
      const timer = setInterval(() => {
        setLoadingProgress((prev) => {
          if (prev >= 100) {
            clearInterval(timer);
            // Store username and navigate to chat
            localStorage.setItem('username', username);
            navigate('/chat');
            return 100;
          }
          return prev + 5;
        });
      }, 100);
      return () => clearInterval(timer);
    }
  }, [isLoading, username, navigate]);

  const handleSubmit = (e) => {
    e.preventDefault();
    if (username.trim()) {
      setIsLoading(true);
    }
  };

  return (
    <LoginContainer>
      <GlassPanel component="form" onSubmit={handleSubmit}>
        <GlitchTitle variant="h1">CYBERNETICA</GlitchTitle>
        
        <Typography variant="subtitle1" sx={{ color: '#00f7ff', mb: 3, textAlign: 'center' }}>
          Authentication required for neural interface
        </Typography>

        <CyberInput
          fullWidth
          placeholder="// ENTER AGENT ID"
          variant="outlined"
          value={username}
          onChange={(e) => setUsername(e.target.value)}
          required
        />

        <CyberInput
          fullWidth
          placeholder="// NEURAL KEY"
          type="password"
          variant="outlined"
          value={password}
          onChange={(e) => setPassword(e.target.value)}
          required
        />

        {isLoading ? (
          <Box sx={{ mt: 3 }}>
            <Typography sx={{ 
              color: '#00f7ff', 
              mb: 1,
              fontSize: { xs: '0.9rem', sm: '1rem' },
              textAlign: 'center'
            }}>
              Initiating neural scan... {loadingProgress}%
            </Typography>
            <LinearProgress
              variant="determinate"
              value={loadingProgress}
              sx={{
                height: { xs: 6, sm: 8 },
                borderRadius: { xs: 3, sm: 4 },
                backgroundColor: 'rgba(0, 247, 255, 0.2)',
                '& .MuiLinearProgress-bar': {
                  background: 'linear-gradient(90deg, #00f7ff, #7b2dff)',
                  borderRadius: { xs: 3, sm: 4 },
                },
              }}
            />
          </Box>
        ) : (
          <CyberButton 
            fullWidth 
            type="submit" 
            variant="contained"
            disabled={!username.trim() || !password.trim()}
          >
            INITIALIZE CONNECTION
          </CyberButton>
        )}

        <AlternativeLogin>
          <IconWrapper>
            <MicIcon />
          </IconWrapper>
          <IconWrapper>
            <FingerprintIcon />
          </IconWrapper>
          <IconWrapper>
            <QrCode2Icon />
          </IconWrapper>
        </AlternativeLogin>
      </GlassPanel>
    </LoginContainer>
  );
}

export default Login; 